import catalog from './catalog.json'

// The whole library in one place: collections (Bible, Quran, Tanakh, ...), their books,
// chapters and translations. Generated by scripts/build-texts.mjs; never edit catalog.json.

export type BookMeta = {
  slug: string
  name: string
  abbr?: string
  title?: string
  aliases?: string[]
  chapterNames?: string[]
  verseStart?: number[]
  lengths: number[]
}

export type Collection = {
  id: string
  name: string
  description: string
  tradition: string
  translations: string[]
  original?: string
  chapterLabel: string
  verseLabel: string
  xref?: boolean
  seo?: boolean
  single?: boolean
  poetry?: boolean
  juz?: [number, number][]
  groups?: { name: string; from: number; to: number }[]
  books: BookMeta[]
}

export type Translation = {
  id: string
  collection: string
  short: string
  name: string
  year: number
  license: string
  lang: string
  dir: 'ltr' | 'rtl'
}

export type Tradition = { id: string; name: string; collections: string[] }

export const COLLECTIONS = catalog.collections as Collection[]
export const TRANSLATIONS = catalog.translations as Translation[]
export const TRADITIONS = catalog.traditions as Tradition[]

const byId = new Map(COLLECTIONS.map((c) => [c.id, c]))
const tById = new Map(TRANSLATIONS.map((t) => [t.id, t]))

export function collectionById(id: string): Collection {
  return byId.get(id) ?? COLLECTIONS[0]
}
export function hasCollection(id: string) {
  return byId.has(id)
}
export function translationById(id: string): Translation {
  return tById.get(id) ?? TRANSLATIONS[0]
}
export function translationsOf(c: string): Translation[] {
  return collectionById(c).translations.map((id) => translationById(id))
}

export function bookIndexBySlug(c: string, slug: string): number | undefined {
  const i = collectionById(c).books.findIndex((b) => b.slug === slug)
  return i === -1 ? undefined : i
}

/** A location in the library. book is a 0-based index into the collection's books. */
export type Ref = { c: string; book: number; chapter: number; verse?: number; endVerse?: number }

export function refKey(c: string, book: number, chapter: number, verse: number) {
  return `${c}.${book}.${chapter}.${verse}`
}

/** Keys saved before the library grew were Bible-only: "book.chapter.verse". */
export function parseKey(key: string): Ref {
  const parts = key.split('.')
  if (parts.length === 3) return { c: 'bible', book: +parts[0], chapter: +parts[1], verse: +parts[2] }
  return { c: parts[0], book: +parts[1], chapter: +parts[2], verse: +parts[3] }
}

export function migrateKey(key: string) {
  return key.split('.').length === 3 ? `bible.${key}` : key
}

export function chapterCount(c: string, book: number) {
  return collectionById(c).books[book]?.lengths.length ?? 0
}

/** The number shown beside a verse. The Dhammapada numbers its verses straight through. */
export function displayVerse(c: string, book: number, chapter: number, verse: number) {
  const start = collectionById(c).books[book]?.verseStart?.[chapter - 1]
  return start ? start + verse - 1 : verse
}

function bookName(c: string, book: number) {
  const col = collectionById(c)
  return col.single ? col.name : col.books[book].name
}

/** "John 3:16", "Quran 2:255", "Dhammapada 183", "Analects 2.4.1". */
export function refLabel(ref: Ref, short = false): string {
  const col = collectionById(ref.c)
  const b = col.books[ref.book]
  if (!b) return ''
  if (col.id === 'dhammapada' && ref.verse) {
    const n = displayVerse(ref.c, ref.book, ref.chapter, ref.verse)
    const end = ref.endVerse && ref.endVerse !== ref.verse ? `–${displayVerse(ref.c, ref.book, ref.chapter, ref.endVerse)}` : ''
    return `Dhammapada ${n}${end}`
  }
  if (col.id === 'analects') {
    return `Analects ${ref.book + 1}.${ref.chapter}${ref.verse ? `.${ref.verse}` : ''}`
  }
  const full = short && b.abbr ? b.abbr : bookName(ref.c, ref.book)
  const name = full === 'Psalms' ? 'Psalm' : full // "Psalm 23:1", never "Psalms 23:1"
  if (!ref.verse) return `${name} ${ref.chapter}`
  const end = ref.endVerse && ref.endVerse !== ref.verse ? `–${ref.endVerse}` : ''
  return `${name} ${ref.chapter}:${ref.verse}${end}`
}

/** Heading for a chapter page. */
export function chapterTitle(c: string, book: number, chapter: number): { title: string; subtitle?: string } {
  const col = collectionById(c)
  const b = col.books[book]
  const named = b.chapterNames?.[chapter - 1]
  if (c === 'quran') return { title: `Surah ${chapter}`, subtitle: named }
  if (c === 'analects') return { title: `Analects ${book + 1}.${chapter}`, subtitle: b.title ? `Book ${book + 1}: ${b.title}` : undefined }
  if (col.single) return { title: `${col.name} ${chapter}`, subtitle: named }
  return { title: `${b.name === 'Psalms' ? 'Psalm' : b.name} ${chapter}` }
}

/**
 * Collections marked seo get a pre-rendered page per chapter (the Bible, Quran and the
 * short texts). The rest open in the client reader, which keeps the site small.
 */
export function chapterHref(c: string, book: number, chapter: number, verse?: number) {
  const col = collectionById(c)
  const hash = verse ? `#v${verse}` : ''
  if (col.seo) return `/read/${c}/${col.books[book].slug}/${chapter}/${hash}`
  return `/reader/?c=${c}&b=${col.books[book].slug}&ch=${chapter}${hash}`
}

export function collectionHref(c: string) {
  return `/read/${c}/`
}

export function neighbor(c: string, book: number, chapter: number, dir: 1 | -1): { book: number; chapter: number } | null {
  const books = collectionById(c).books
  let b = book
  let ch = chapter + dir
  if (ch < 1) {
    b -= 1
    if (b < 0) return null
    ch = books[b].lengths.length
  } else if (ch > books[b].lengths.length) {
    b += 1
    if (b >= books.length) return null
    ch = 1
  }
  return { book: b, chapter: ch }
}

/** The collections a reader sees: their picks, or everything if they picked nothing. */
export function visibleCollections(library: string[] | null): Collection[] {
  if (!library || library.length === 0) return COLLECTIONS
  return COLLECTIONS.filter((c) => library.includes(c.id))
}

export function groupOf(c: string, book: number): string | undefined {
  return collectionById(c).groups?.find((g) => book >= g.from && book <= g.to)?.name
}
